import "server-only";

import path from "node:path";

import { createOpenAPI } from "fumadocs-openapi/server";

/**
 * Schema id `"openapi.snapshot.json"` is the stable key that `<APIPage>`
 * references via the `document` prop; `path.resolve` runs once server-side so
 * MDX stays portable. Snapshot is regenerated by `tests/contract/openapi.test.ts`
 * from the live Zod validators — the rendered API reference can't drift.
 */
export const openapi = createOpenAPI({
  input: () => ({
    "openapi.snapshot.json": path.resolve("./openapi.snapshot.json"),
  }),
});
